## Installation

```bash
npx shadcn@latest add https://akoder.xyz/r/dotted-world-map.json
```

## Usage

```tsx
import { DottedWorldMap } from "@/components/ui/dotted-world-map";

const points = [
  { name: "London", lat: 51.5074, lng: -0.1278, value: 0.9, radius: 12 },
  { name: "Tokyo", lat: 35.6762, lng: 139.6503, value: 0.8, radius: 12 },
  { name: "New York", lat: 40.7128, lng: -74.006, value: 0.95, radius: 13 },
];

export function VisitorsMap() {
  return <DottedWorldMap points={points} />;
}
```

