## Usage

```tsx
import { ContactChannels } from "@/components/ui/contact-channels";
import { Github, Mail } from "lucide-react";

const channels = [
  { id: "github", platform: "github", handle: "@octocat", href: "https://github.com", action: "external", icon: <Github className="size-4" /> },
  { id: "email", platform: "email", handle: "hi@example.com", action: "copy", copyValue: "hi@example.com", shortcutKey: "e", icon: <Mail className="size-4" /> },
];

export function Contact() {
  return <ContactChannels items={channels} columns={2} />;
}
```
